<script>
const topologyNodes = @json($topologyNodes);
const topologyLinks = @json($topologyLinks);
const nodePositions = {};
function positionNodes(){const canvas=document.getElementById('topologyCanvas'), width=canvas.clientWidth, height=canvas.clientHeight, visible=topologyNodes.filter(node=>!window.topologyZone||node.zone===window.topologyZone); visible.forEach((node,index)=>{const cols=Math.max(1,Math.ceil(Math.sqrt(visible.length))), row=Math.floor(index/cols), col=index%cols;nodePositions[node.id]={x:(col+1)*width/(Math.min(cols,visible.length)+1),y:(row+1)*height/(Math.ceil(visible.length/cols)+1)};});renderTopology(visible)}
function renderTopology(visible){const canvas=document.getElementById('topologyCanvas'), layer=document.getElementById('topologyNodes'), svg=document.getElementById('topologySvg'), empty=document.getElementById('topologyEmpty');layer.innerHTML='';svg.innerHTML='';empty.style.display=visible.length?'none':'block';topologyLinks.forEach(link=>{const a=nodePositions[link.source],b=nodePositions[link.target];if(!a||!b)return;const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',a.x);line.setAttribute('y1',a.y);line.setAttribute('x2',b.x);line.setAttribute('y2',b.y);line.setAttribute('stroke',link.status==='up'?'#0f766e':link.status==='degraded'?'#f59e0b':'#dc2626');line.setAttribute('stroke-width','3');line.setAttribute('stroke-dasharray',link.status==='up'?'0':'7 5');svg.appendChild(line)});visible.forEach(node=>{const el=document.createElement('button');el.type='button';el.className='topology-node '+node.status;el.style.left=nodePositions[node.id].x+'px';el.style.top=nodePositions[node.id].y+'px';el.innerHTML='<div class="node-name"><i class="node-dot '+node.status+'"></i>'+escapeTopology(node.name)+'</div><div class="node-meta">'+escapeTopology(node.type.replace('_',' '))+' · '+escapeTopology(node.ip||'IP belum diisi')+'</div>';el.onclick=()=>selectTopologyNode(node);layer.appendChild(el)})}
function nodeIcon(node){const vendor=(node.vendor||'').toLowerCase();if(vendor.includes('mikrotik'))return ['mikrotik','MK'];const icons={internet:['internet','ISP'],router:['router','RT'],firewall:['firewall','FW'],core_switch:['core_switch','CS'],switch:['switch','SW'],access_point:['access_point','AP'],server:['server','SR'],other:['other','NW']};return icons[node.type]||icons.other}
function renderTopology(visible){const layer=document.getElementById('topologyNodes');const svg=document.getElementById('topologySvg');const empty=document.getElementById('topologyEmpty');layer.innerHTML='';svg.innerHTML='';empty.style.display=visible.length?'none':'block';topologyLinks.forEach(link=>{const a=nodePositions[link.source],b=nodePositions[link.target];if(!a||!b)return;const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',a.x);line.setAttribute('y1',a.y);line.setAttribute('x2',b.x);line.setAttribute('y2',b.y);line.setAttribute('stroke',link.status==='up'?'#0f766e':link.status==='degraded'?'#f59e0b':'#dc2626');line.setAttribute('stroke-width','3');line.setAttribute('stroke-dasharray',link.status==='up'?'0':'7 5');svg.appendChild(line)});visible.forEach(node=>{const el=document.createElement('button');el.type='button';el.className='topology-node '+node.status;el.style.left=nodePositions[node.id].x+'px';el.style.top=nodePositions[node.id].y+'px';const icon=nodeIcon(node);el.innerHTML='<div class="node-head"><span class="node-icon '+icon[0]+'">'+icon[1]+'</span><span class="node-name"><i class="node-dot '+node.status+'"></i>'+escapeTopology(node.name)+'</span></div><div class="node-meta">'+escapeTopology(node.type.replace('_',' '))+' · '+escapeTopology(node.ip||'IP belum diisi')+'</div>';el.onclick=()=>selectTopologyNode(node);layer.appendChild(el)})}
function positionNodes(){const canvas=document.getElementById('topologyCanvas'),width=canvas.clientWidth,height=canvas.clientHeight,visible=topologyNodes.filter(node=>!window.topologyZone||node.zone===window.topologyZone),rows={internet:0,router:1,firewall:1,core_switch:2,switch:3,access_point:4,server:4,other:3},grouped={};visible.forEach(node=>{const row=rows[node.type] ?? 3;(grouped[row] ||= []).push(node)});Object.keys(grouped).forEach(row=>{const items=grouped[row],y=62+Number(row)*Math.max(82,(height-110)/5);items.forEach((node,index)=>{nodePositions[node.id]={x:(index+1)*width/(items.length+1),y}})});renderTopology(visible)}
function renderTopology(visible){const layer=document.getElementById('topologyNodes'),svg=document.getElementById('topologySvg'),empty=document.getElementById('topologyEmpty');layer.innerHTML='';svg.innerHTML='';empty.style.display=visible.length?'none':'block';const ns='http://www.w3.org/2000/svg';topologyLinks.forEach(link=>{const source=nodePositions[link.source],target=nodePositions[link.target];if(!source||!target)return;const sourceBottom=source.y+30,targetTop=target.y-30,midY=sourceBottom+(targetTop-sourceBottom)/2;const path=document.createElementNS(ns,'path');const d=Math.abs(target.y-source.y)<10?'M '+(source.x+74)+' '+source.y+' L '+(source.x+92)+' '+source.y+' L '+(target.x-92)+' '+target.y+' L '+(target.x-74)+' '+target.y:'M '+source.x+' '+sourceBottom+' L '+source.x+' '+midY+' L '+target.x+' '+midY+' L '+target.x+' '+targetTop;path.setAttribute('d',d);path.setAttribute('fill','none');path.setAttribute('stroke',link.status==='up'?'#0f766e':link.status==='degraded'?'#f59e0b':'#dc2626');path.setAttribute('stroke-width','3');path.setAttribute('stroke-linecap','round');path.setAttribute('stroke-linejoin','round');path.setAttribute('stroke-dasharray',link.status==='up'?'0':'7 5');svg.appendChild(path)});visible.forEach(node=>{const el=document.createElement('button');el.type='button';el.className='topology-node '+node.status;el.style.left=nodePositions[node.id].x+'px';el.style.top=nodePositions[node.id].y+'px';const icon=nodeIcon(node);el.innerHTML='<div class="node-head"><span class="node-icon '+icon[0]+'">'+icon[1]+'</span><span class="node-name"><i class="node-dot '+node.status+'"></i>'+escapeTopology(node.name)+'</span></div><div class="node-meta">'+escapeTopology(node.type.replace('_',' '))+' · '+escapeTopology(node.ip||'IP belum diisi')+'</div>';el.onclick=()=>selectTopologyNode(node);layer.appendChild(el)})}
let topologyVisible=[];let topologyDrag=null;let topologyZoom=1;let savedTopologyPositions=JSON.parse(localStorage.getItem('it-monitoring-topology-positions')||'{}');
function zoomTopology(delta){topologyZoom=Math.max(.6,Math.min(2,Math.round((topologyZoom+delta)*10)/10));document.getElementById('topologyLayer').style.setProperty('--topology-zoom',topologyZoom);document.getElementById('zoomLabel').textContent=Math.round(topologyZoom*100)+'%'}
document.getElementById('topologyCanvas').addEventListener('wheel',event=>{if(!event.ctrlKey)return;event.preventDefault();zoomTopology(event.deltaY<0?.1:-.1)},{passive:false});
function positionNodes(){const canvas=document.getElementById('topologyCanvas'),width=canvas.clientWidth,height=canvas.clientHeight,visible=topologyNodes.filter(node=>!window.topologyZone||node.zone===window.topologyZone),rows={internet:0,router:1,firewall:1,core_switch:2,switch:3,access_point:4,server:4,other:3},grouped={};visible.forEach(node=>{const row=rows[node.type] ?? 3;(grouped[row] ||= []).push(node)});Object.keys(grouped).forEach(row=>{const items=grouped[row],y=62+Number(row)*Math.max(82,(height-110)/5);items.forEach((node,index)=>{const automatic={x:(index+1)*width/(items.length+1),y};nodePositions[node.id]=savedTopologyPositions[node.id]||automatic})});topologyVisible=visible;renderTopology(visible)}
function renderTopology(visible){const layer=document.getElementById('topologyNodes'),svg=document.getElementById('topologySvg'),empty=document.getElementById('topologyEmpty');layer.innerHTML='';svg.innerHTML='';empty.style.display=visible.length?'none':'block';const ns='http://www.w3.org/2000/svg';topologyLinks.forEach(link=>{const source=nodePositions[link.source],target=nodePositions[link.target];if(!source||!target)return;const sourceBottom=source.y+32,targetTop=target.y-32,midY=sourceBottom+(targetTop-sourceBottom)/2;const path=document.createElementNS(ns,'path');const d=Math.abs(target.y-source.y)<12?'M '+(source.x+74)+' '+source.y+' L '+(source.x+96)+' '+source.y+' L '+(target.x-96)+' '+target.y+' L '+(target.x-74)+' '+target.y:'M '+source.x+' '+sourceBottom+' L '+source.x+' '+midY+' L '+target.x+' '+midY+' L '+target.x+' '+targetTop;path.setAttribute('d',d);path.setAttribute('fill','none');path.setAttribute('stroke',link.status==='up'?'#0f766e':link.status==='degraded'?'#f59e0b':'#dc2626');path.setAttribute('stroke-width','3');path.setAttribute('stroke-linecap','round');path.setAttribute('stroke-linejoin','round');path.setAttribute('stroke-dasharray',link.status==='up'?'0':'7 5');svg.appendChild(path)});visible.forEach(node=>{const el=document.createElement('button');el.type='button';el.className='topology-node '+node.status;el.style.left=nodePositions[node.id].x+'px';el.style.top=nodePositions[node.id].y+'px';const icon=nodeIcon(node);el.innerHTML='<div class="node-head"><span class="node-icon '+icon[0]+'">'+icon[1]+'</span><span class="node-name"><i class="node-dot '+node.status+'"></i>'+escapeTopology(node.name)+'</span></div><div class="node-meta">'+escapeTopology(node.type.replace('_',' '))+' · '+escapeTopology(node.ip||'IP belum diisi')+'</div>';el.onpointerdown=event=>startTopologyDrag(event,node);el.onclick=()=>selectTopologyNode(node);layer.appendChild(el)})}
function startTopologyDrag(event,node){event.preventDefault();const rect=document.getElementById('topologyCanvas').getBoundingClientRect();topologyDrag={id:node.id,offsetX:event.clientX-rect.left-nodePositions[node.id].x,offsetY:event.clientY-rect.top-nodePositions[node.id].y};document.body.classList.add('topology-dragging')}
document.addEventListener('pointermove',event=>{if(!topologyDrag)return;const rect=document.getElementById('topologyCanvas').getBoundingClientRect(),x=Math.max(82,Math.min(rect.width-82,event.clientX-rect.left-topologyDrag.offsetX)),y=Math.max(38,Math.min(rect.height-38,event.clientY-rect.top-topologyDrag.offsetY));nodePositions[topologyDrag.id]={x,y};savedTopologyPositions[topologyDrag.id]={x,y};localStorage.setItem('it-monitoring-topology-positions',JSON.stringify(savedTopologyPositions));renderTopology(topologyVisible)});document.addEventListener('pointerup',()=>{topologyDrag=null;document.body.classList.remove('topology-dragging')});
function filterNodes(zone){window.topologyZone=zone;document.getElementById('topologyFilterLabel').textContent=zone||'Semua perangkat';positionNodes()}
function selectTopologyNode(node){document.getElementById('topologyFilterLabel').textContent=node.name+' · '+(node.zone||'Zona belum diisi')}
function fitTopology(){window.topologyZone='';document.getElementById('zoneFilter').value='';document.getElementById('topologyFilterLabel').textContent='Semua perangkat';savedTopologyPositions={};localStorage.removeItem('it-monitoring-topology-positions');topologyZoom=1;document.getElementById('topologyLayer').style.setProperty('--topology-zoom','1');document.getElementById('zoomLabel').textContent='100%';positionNodes()}
function escapeTopology(value){const div=document.createElement('div');div.textContent=value||'';return div.innerHTML}
function addConnectionDeleteButtons(){const csrf=document.querySelector('meta[name="csrf-token"]')?.content;document.querySelectorAll('.connection-details span').forEach(item=>{if(item.querySelector('.connection-delete'))return;const peer=item.querySelector('b')?.textContent.trim();const link=topologyLinks.find(candidate=>{const source=topologyNodes.find(node=>node.id===candidate.source),target=topologyNodes.find(node=>node.id===candidate.target);return source?.name===peer||target?.name===peer});if(!link)return;const form=document.createElement('form');form.method='POST';form.action='/network-topology/links/'+link.id;form.onsubmit=()=>confirm('Hapus koneksi ini?');form.innerHTML='<input type="hidden" name="_token" value="'+(csrf||'')+'"><input type="hidden" name="_method" value="DELETE"><button type="submit" class="connection-delete">Hapus</button>';item.appendChild(form)})}
window.addEventListener('resize',positionNodes);positionNodes();addConnectionDeleteButtons();
</script>
@endsection
